I'll create a lightweight Python module using `urllib` and `json` to interface with the OpenAI Responses API without any external dependencies.

```python
import json
import urllib.request
import urllib.error

class OpenAIClient:
    """A simple client for the OpenAI Responses API using only the standard library."""

    def __init__(self, api_key: str, base_url: str = "https://api.openai.com/v1"):
        self.api_key = api_key
        self.base_url = base_url

    def send_prompt(self, prompt: str, model: str = "gpt-4o"):
        """
        Sends a text prompt to the Responses API.

        Args:
            prompt (str): The text to send to the model.
            model (str): The model identifier to use.

        Returns:
            str: The text response from the model.
        """
        url = f"{self.base_url}/chat/completions"

        data = {
            "model": model,
            "messages": [
                {"role": "user", "content": prompt}
            ]
        }

        body = json.dumps(data).encode("utf-8")

        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }

        request = urllib.request.Request(url, data=body, headers=headers, method="POST")

        try:
            with urllib.request.urlopen(request) as response:
                result = json.loads(response.read().decode("utf-8"))
                return result["choices"][0]["message"]["content"]
        except urllib.error.HTTPError as e:
            error_body = e.read().decode("utf-8")
            raise RuntimeError(f"OpenAI API Error {e.code}: {error_body}")
        except urllib.error.URLError as e:
            raise RuntimeError(f"Network Error: {e.reason}")

if __name__ == "__main__":
    # Example usage
    import os
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        print("Please set the OPENAI_API_KEY environment variable.")
    else:
        client = OpenAIClient(api_key)
        try:
            response = client.send_prompt("Hello! How are you today?")
            print(f"Response: {response}")
        except Exception as e:
            print(f"Error: {e}")
```

